contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(wagerAmount > 0, "wagerAmount must be positive");
        require(address(this).balance >= wagerAmount, "not enough balance");

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(wagerAmount); if (__ESBMC_reverted()) return;
        c.wager{value: wagerAmount}(); if (__ESBMC_reverted()) return;

        bool wageredBefore = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        c.play(); if (__ESBMC_reverted()) return;

        bool wageredAfter = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(wageredBefore && !wageredAfter);
    }

    receive() external payable {}
}

